// Inclement layer: Inclement Emerald's deliberate base stat buffs and Ability
// slots, applied on top of gSpeciesInfo for every Pokemon that is not
// trainer-owned (wild, player-owned, gifts, eggs; see IsMonTrainerOwned).
// Trainer, partner, facility and Champions Circuit Pokemon never read it.
//
// Base stats are the whole line in HP/Atk/Def/SpA/SpD/Spe order; each stat is
// max(gSpeciesInfo, Inclement), so the layer never lowers a stat. Abilities are
// the whole slot line; slot numbers are shared with gSpeciesInfo, so a
// Pokemon keeps its ability slot and only the Ability in that slot differs.
// Not layered: official changes after Inclement (e.g. Cresselia, Shiftry),
// species this game authored itself (its own Megas, Mega Meganium,
// Hitmonchan) and slots its earlier Inclement Ability port already decided.
#define INCLEMENT_BASE_STATS(hp, atk, def, spAtk, spDef, speed) \
    .hasBaseStats = TRUE, .baseStats = { [STAT_HP] = hp, [STAT_ATK] = atk, [STAT_DEF] = def, \
                                         [STAT_SPATK] = spAtk, [STAT_SPDEF] = spDef, [STAT_SPEED] = speed }
#define INCLEMENT_ABILITIES(a0, a1, a2) .hasAbilities = TRUE, .abilities = { a0, a1, a2 }

